// Pokémon instances, Gen-3 stat math, exp curves, evolution, items.
window.Pkmn = (() => {

  // Exp required to reach a level, by growth rate (Gen 1 species use these four).
  function expForLevel(growth, n) {
    if (n <= 1) return 0;
    switch (growth) {
      case 'fast': return Math.floor(4 * n * n * n / 5);
      case 'slow': return Math.floor(5 * n * n * n / 4);
      case 'medium-slow': return Math.floor(6 / 5 * n * n * n) - 15 * n * n + 100 * n - 140;
      default: return n * n * n; // medium-fast
    }
  }

  function levelForExp(growth, exp) {
    let lv = 1;
    while (lv < 100 && expForLevel(growth, lv + 1) <= exp) lv++;
    return lv;
  }

  const STAT_KEYS = ['hp', 'atk', 'def', 'spa', 'spd', 'spe'];

  function calcStats(species, level, ivs) {
    const b = species.stats;
    const st = {};
    st.hp = Math.floor((2 * b.hp + ivs.hp) * level / 100) + level + 10;
    for (const k of ['atk', 'def', 'spa', 'spd', 'spe'])
      st[k] = Math.floor((2 * b[k] + ivs[k]) * level / 100) + 5;
    return st;
  }

  function randomIVs() {
    const ivs = {};
    for (const k of STAT_KEYS) ivs[k] = (Math.random() * 32) | 0;
    return ivs;
  }

  // Latest 4 level-up moves at or below `level`.
  function movesAtLevel(species, level) {
    const learned = species.learnset.filter(l => l.level <= level && MOVES[l.move]);
    const seen = new Set(), out = [];
    for (let i = learned.length - 1; i >= 0 && out.length < 4; i--) {
      if (!seen.has(learned[i].move)) { seen.add(learned[i].move); out.unshift(learned[i].move); }
    }
    return out.length ? out : ['tackle'];
  }

  function make(id, level) {
    const sp = POKEDEX[id];
    const ivs = randomIVs();
    const stats = calcStats(sp, level, ivs);
    return {
      id, level, ivs,
      nickname: null,
      exp: expForLevel(sp.growth, level),
      hp: stats.hp,
      stats,
      moves: movesAtLevel(sp, level).map(m => ({ name: m, pp: MOVES[m].pp, maxPp: MOVES[m].pp })),
      status: null, // 'psn'|'brn'|'par'|'slp'|'frz'
      sleepTurns: 0,
    };
  }

  const species = (mon) => POKEDEX[mon.id];
  const dname = (mon) => (mon.nickname ?? species(mon).displayName).toUpperCase();

  function recalc(mon) {
    const old = mon.stats.hp;
    mon.stats = calcStats(species(mon), mon.level, mon.ivs);
    mon.hp = Math.min(mon.stats.hp, mon.hp + (mon.stats.hp - old)); // HP gain carries over
  }

  // Returns array of move names newly learnable at exactly this level.
  function movesLearnedAt(mon, level) {
    return species(mon).learnset
      .filter(l => l.level === level && MOVES[l.move] && !mon.moves.some(m => m.name === l.move))
      .map(l => l.move);
  }

  // Level-based evolution check. Returns target species id or null.
  function levelEvolution(mon) {
    for (const e of species(mon).evolvesTo)
      if (e.method === 'level' && mon.level >= e.level) return e.to;
    return null;
  }
  function stoneEvolution(mon, stoneItem) {
    for (const e of species(mon).evolvesTo)
      if (e.method === 'stone' && e.item === stoneItem) return e.to;
    return null;
  }

  function evolve(mon, toId) {
    mon.id = toId;
    recalc(mon);
  }

  function expGain(defeated, isTrainer) {
    const base = species(defeated).baseExp ?? 60;
    return Math.max(1, Math.floor(base * defeated.level / 7 * (isTrainer ? 1.5 : 1)));
  }

  // ---- Items ---------------------------------------------------------------
  const ITEMS = {
    'poke-ball':   { name: 'POKé BALL',   price: 200,  kind: 'ball', mult: 1 },
    'great-ball':  { name: 'GREAT BALL',  price: 600,  kind: 'ball', mult: 1.5 },
    'ultra-ball':  { name: 'ULTRA BALL',  price: 1200, kind: 'ball', mult: 2 },
    'potion':      { name: 'POTION',      price: 300,  kind: 'heal', amount: 20 },
    'super-potion':{ name: 'SUPER POTION',price: 700,  kind: 'heal', amount: 50 },
    'hyper-potion':{ name: 'HYPER POTION',price: 1200, kind: 'heal', amount: 200 },
    'full-heal':   { name: 'FULL HEAL',   price: 600,  kind: 'status' },
    'revive':      { name: 'REVIVE',      price: 1500, kind: 'revive' },
    'fire-stone':  { name: 'FIRE STONE',  price: 2100, kind: 'stone' },
    'water-stone': { name: 'WATER STONE', price: 2100, kind: 'stone' },
    'thunder-stone':{name: 'THUNDER STONE',price: 2100,kind: 'stone' },
    'leaf-stone':  { name: 'LEAF STONE',  price: 2100, kind: 'stone' },
    'moon-stone':  { name: 'MOON STONE',  price: 2100, kind: 'stone' },
    'old-rod':     { name: 'OLD ROD',     price: 0,    kind: 'key' },
  };

  return {
    make, species, dname, recalc, calcStats, expForLevel, levelForExp,
    movesAtLevel, movesLearnedAt, levelEvolution, stoneEvolution, evolve,
    expGain, ITEMS, STAT_KEYS,
  };
})();
